/* @lc app=leetcode id=1520 lang=kotlin */ class Solution { fun maxNumOfSubstrings(s: String): List<String> = ('a'..'z').associateWith { s.indexOf(it) }.let { fi -> ('a'..'z').associateWith { s.lastIndexOf(it) }.let { la -> ('a'..'z').filter { fi[it]!! >= 0 }.mapNotNull { c -> fi[c]!!.let { l -> generateSequence(Triple(l, la[c]!!, true)) { (i, r, ok) -> if (i > r) null else Triple(i + 1, maxOf(r, la[s[i]]!!), ok && fi[s[i]]!! >= l) }.last().let { (_, r, ok) -> if (ok) l to r else null } } }.sortedBy { it.second }.fold(listOf<Pair<Int, Int>>()) { acc, (l, r) -> if (acc.isEmpty() || l > acc.last().second) acc + (l to r) else acc }.map { s.substring(it.first, it.second + 1) } } } }